import{_ as e,c as a,o as r,a5 as o}from"./chunks/framework.DorIfSpC.js";const m=JSON.parse('{"title":"星智未來","description":"星智未來專注於 AI 應用工程，分享 AI、機器人、LLM 實戰筆記與專案故事，以工程實踐創造價值。","frontmatter":{"layout":"home","title":"星智未來","description":"星智未來專注於 AI 應用工程，分享 AI、機器人、LLM 實戰筆記與專案故事，以工程實踐創造價值。","hero":{"name":"星智未來","text":"以 AI 工程，快速把點子變成價值","tagline":"我們分享實戰筆記、專案故事與教學，持續更新。","actions":[{"theme":"brand","text":"AI 文章","link":"/ai/"},{"theme":"alt","text":"機器人文章","link":"/robot/"},{"theme":"alt","text":"專案文章","link":"/project/"}]},"features":[{"title":"AI","details":"最新 AI 技術與應用分享。","link":"/ai/"},{"title":"機器人","details":"機器人最新發展","link":"/robot/"},{"title":"專案","details":"我們的專案展示與經驗分享。","link":"/project/"},{"title":"學習","details":"長期學習路徑的筆記與心得。","link":"/learning/"}],"head":[["link",{"rel":"canonical","href":"https://blog.aidream.com.tw/"}],["meta",{"property":"og:url","content":"https://blog.aidream.com.tw/"}],["meta",{"property":"og:description","content":"星智未來專注於 AI 應用工程，分享 AI、機器人、LLM 實戰筆記與專案故事，以工程實踐創造價值。"}],["meta",{"name":"twitter:description","content":"星智未來專注於 AI 應用工程，分享 AI、機器人、LLM 實戰筆記與專案故事，以工程實踐創造價值。"}],["meta",{"property":"og:title","content":"星智未來 | 星智未來"}],["meta",{"name":"twitter:title","content":"星智未來 | 星智未來"}]]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1787544889000}'),i={name:"index.md"};function n(l,t,s,h,p,c){return r(),a("div",null,[...t[0]||(t[0]=[o('<h2 id="📝-最新文章" tabindex="-1">📝 最新文章 <a class="header-anchor" href="#📝-最新文章" aria-label="Permalink to &quot;📝 最新文章&quot;">​</a></h2><h3 id="為什麼每天摸一下貓的頭-是一件宇宙學意義的事" tabindex="-1"><a href="/project/migato-cosmic-ritual">為什麼每天摸一下貓的頭，是一件宇宙學意義的事</a> <a class="header-anchor" href="#為什麼每天摸一下貓的頭-是一件宇宙學意義的事" aria-label="Permalink to &quot;[為什麼每天摸一下貓的頭，是一件宇宙學意義的事](/project/migato-cosmic-ritual)&quot;">​</a></h3><p><strong>專案</strong> · 2026-03-20</p><p>從易經到塔羅，人類花了三千年設計觀測工具。Migato 米果把這套古老的儀式，變成每天早上摸一下頭的動作——讓你帶著意圖出門。</p><hr><h3 id="那張-ai-影片比價表-少了一列" tabindex="-1"><a href="/project/ai-video-cost-selfhost">那張 AI 影片比價表，少了一列</a> <a class="header-anchor" href="#那張-ai-影片比價表-少了一列" aria-label="Permalink to &quot;[那張 AI 影片比價表，少了一列](/project/ai-video-cost-selfhost)&quot;">​</a></h3><p><strong>專案</strong> · 2026-08-22</p><p>社群流傳的 AI 影片比價表有八個方案，就是沒有自架那一列。用兩週的實測數字補上去：同一個模型自己跑，比官方 API 便宜 4.9 倍，年費零。</p><hr><h3 id="我把上一篇刪掉的那一步-加了回來" tabindex="-1"><a href="/project/storyboard-before-render">我把上一篇刪掉的那一步，加了回來</a> <a class="header-anchor" href="#我把上一篇刪掉的那一步-加了回來" aria-label="Permalink to &quot;[我把上一篇刪掉的那一步，加了回來](/project/storyboard-before-render)&quot;">​</a></h3><p><strong>專案</strong> · 2026-08-20</p><p>刪掉關鍵幀之後，我連「先看一眼」也一起刪掉了。九張 20 秒的分鏡草圖抓到三個錯——每一個在影片階段都要八分鐘才會浮出來。</p><hr><h3 id="我刪掉了-ai-影片製作工作流裡最貴的那一步" tabindex="-1"><a href="/project/minimax-h3-ref2va">我刪掉了 AI 影片製作工作流裡最貴的那一步</a> <a class="header-anchor" href="#我刪掉了-ai-影片製作工作流裡最貴的那一步" aria-label="Permalink to &quot;[我刪掉了 AI 影片製作工作流裡最貴的那一步](/project/minimax-h3-ref2va)&quot;">​</a></h3><p><strong>專案</strong> · 2026-08-14</p><p>用 MiniMax H3 的 Ref2VA 模式，只給角色參考照就生出多鏡頭影片——43 張關鍵幀、4 到 5 小時的手工篩修，那一段不是變快了，是不存在了。</p><hr><h3 id="為什麼我花兩美金租-gpu-而不是花十二萬買一張" tabindex="-1"><a href="/project/minimax-h3-third-path">為什麼我花兩美金租 GPU，而不是花十二萬買一張</a> <a class="header-anchor" href="#為什麼我花兩美金租-gpu-而不是花十二萬買一張" aria-label="Permalink to &quot;[為什麼我花兩美金租 GPU，而不是花十二萬買一張](/project/minimax-h3-third-path)&quot;">​</a></h3><p><strong>專案</strong> · 2026-08-13</p><p>MiniMax H3 開源了，但一張 5090 要十二萬。在 RunPod 上租一個下午、花兩美金，把租來的機器當成自己的地端——買到的不是算力，是看得見內部。</p>',20)])])}const f=e(i,[["render",n]]);export{m as __pageData,f as default};
